using System.Text.Json;
using TomasAI.IFM.Domain.Reference.Shared.ParameterSets;
using TomasAI.IFM.Domain.MarketData.Analytics.Shared;
using TomasAI.IFM.Domain.MarketData.Shared;
using TomasAI.IFM.Domain.Trade.Shared.Strategy.Workflow.IntrinsicTime.Pipeline.Configuration.RegimeDiscovery;
using TomasAI.IFM.UI.Net.ViewModels.Reference.ParameterSets;
using TomasAI.IFM.Shared.EventSourcing;
namespace TomasAI.IFM.UI.Rust.Bridge.Net;
/// <summary>Parameter UI working copies use the existing lossless editor; persistence stays in the existing domain API.</summary>
public sealed class ParameterSetSession : IAsyncDisposable
{
 public static readonly string[] Actions=["load","resume-parameter","component","select","new-draft","edit-draft","discard","stage-fields","stage-metrics","intervals","save-draft","validate-parameter","publish-parameter","retire-parameter","rename-parameter","schema-parameter","payload-parameter","compare-parameter","audit-parameter","assignment","assign-parameter","disable-assignment","startup-preview","startup-runs","startup-report","signal-monitoring","legacy-parameters","legacy-next","legacy-prev","legacy-preview","legacy-create"];
 readonly RustClientServiceScope? scope;readonly IParameterSetsApi api;readonly ParameterSetEditorModel editor=new();
 ParameterComponentSummary[] components=[];ParameterSetVersion[] versions=[];ParameterLegacyVersion[] legacy=[];
 string component="";int legacyOffset;bool started;ParameterAssignmentSnapshot? assignment;CreateParameterSetCommand? legacyPreview;string legacyPreviewId="";
 readonly Dictionary<string,string> extras=[];
 const string Workflow=TomasAI.IFM.Domain.Trade.Shared.Strategy.Workflow.IntrinsicTime.Identity.IntrinsicTimeStrategyWorkflowDefinition.Id;
 public ParameterSetSession(){scope=new(Environment.GetEnvironmentVariable("IFM_UI_NATS_URL")??"nats://localhost:4222");api=scope.Container.GetInstance<IParameterSetsApi>();}
 public ParameterSetSession(IParameterSetsApi api){this.api=api;}
 public async Task<ContractEditorResult> ExecuteAsync(ContractEditorIntent input)
 {
  using var deadline=new CancellationTokenSource(TimeSpan.FromSeconds(30));var ct=deadline.Token;
  if(scope is not null&&!started){await scope.StartAsync(ct);started=true;}
  if(input.Intent!="load"&&components.Length==0)throw new InvalidOperationException("Load the parameter catalogue first.");
  if(input.Intent is "component" or "select" or "new-draft" && editor.IsEditing)throw new InvalidOperationException("Save or discard the working copy first.");
  if(input.Intent is "publish-parameter" or "retire-parameter" or "rename-parameter" or "assignment" or "assign-parameter" or "disable-assignment" && (editor.IsEditing||editor.Selected is null))throw new InvalidOperationException("Select a saved parameter version first.");
  if(input.Intent is "stage-fields" or "stage-metrics" or "intervals" or "save-draft" or "validate-parameter" or "payload-parameter")Capture(input.Fields);
  switch(input.Intent){
   case "resume-parameter":break;
   case "load":if(editor.IsEditing)throw new InvalidOperationException("Discard the working copy before refreshing.");components=Read(await api.ComponentsAsync(ct));component=components.FirstOrDefault()?.ComponentCode??"";await LoadVersions(ct);break;
   case "component":component=components.Single(x=>x.ComponentCode==input.Fields.GetValueOrDefault("component")).ComponentCode;await LoadVersions(ct);break;
   case "select":var selected=versions.Single(x=>Id(x)==input.OriginalId);editor.Load(selected,versions.Where(x=>x.Reference.SetId==selected.Reference.SetId).Max(x=>x.CatalogRevision));extras.Clear();assignment=null;break;
   case "new-draft":var definition=components.Single(x=>x.ComponentCode==component);if(!definition.CanEdit)throw new InvalidOperationException("This component is read-only.");var horizon=Enum.Parse<TimeFrameType>(input.Fields.GetValueOrDefault("horizon")??"Daily");if(horizon is not (TimeFrameType.Daily or TimeFrameType.Weekly or TimeFrameType.Monthly))throw new ArgumentException("Unsupported horizon.");editor.New(Read(await api.PreviewAsync(Guid.NewGuid(),ct,(int)horizon,componentCode:component)),component,definition.Name);extras.Clear();break;
   case "edit-draft":if(!editor.CanEdit)throw new InvalidOperationException("Unsupported schema or fields are read-only.");if(editor.Selected is null||editor.IsEditing)throw new InvalidOperationException("Select a saved version first.");editor.BeginEdit(Read(await api.PreviewAsync(editor.SetId,ct,(int)(editor.Parameters?.TargetHorizon??TimeFrameType.Daily),editor.Payload(),componentCode:component)));extras.Clear();break;
   case "discard":if(editor.Selected is {} original)editor.Load(original,editor.ExpectedRevision);else editor.Clear();extras.Clear();break;
   case "stage-fields":case "stage-metrics":break;
   case "intervals":if(!editor.IsEditing||editor.Parameters is null)throw new InvalidOperationException("Open a Regime Discovery working copy first.");var intervals=JsonSerializer.Deserialize<RegimeDiscoveryTimeFrameConfiguration[]>(input.Fields["intervals"])??[];if(intervals.Any(x=>!TimeFrames.Contains(x.TimeFrame)||x.Weight<=0||x.MaximumAgeSeconds<=0))throw new ArgumentException("Intervals require positive weights and maximum age.");var source=editor.Parameters with{Horizon=editor.Parameters.Horizon with{TimeFrames=intervals.Select(x=>x with{IsRequired=true}).ToArray()}};editor.BeginEdit(Read(await api.PreviewAsync(editor.SetId,ct,(int)source.TargetHorizon,JsonSerializer.Serialize(source),true,component)));break;
   case "save-draft":if(!editor.IsEditing)throw new InvalidOperationException("Open a working copy first.");var setId=editor.SetId;var operationId=input.RequestId;var result=editor.Selected is null?await api.CreateAsync(new(){CommandId=operationId,EntityId=new(setId),ComponentCode=component,Name=editor.Name,Description=editor.Description,PayloadJson=editor.Payload(),SchemaVersion=editor.SchemaVersion},ct):await api.SaveAsync(new(){CommandId=operationId,EntityId=new(setId),ExpectedRevision=editor.ExpectedRevision,ComponentCode=component,Name=editor.Name,Description=editor.Description,PayloadJson=editor.Payload(),SchemaVersion=editor.SchemaVersion},ct);Read(result);editor.AcknowledgeSave();await Committed(setId,operationId,ct);break;
   case "validate-parameter":extras["validation"]=JsonSerializer.Serialize(Read(await api.ValidateAsync(editor.Payload(),editor.SchemaVersion,ct,component)));break;
   case "publish-parameter":var draft=editor.Selected!;if(draft.Status!=ParameterVersionStatus.Draft)throw new InvalidOperationException("Select a saved draft first.");Read(await api.PublishAsync(new(){CommandId=input.RequestId,EntityId=new(editor.SetId),Version=draft.Reference.Version,ExpectedRevision=editor.ExpectedRevision,ComponentCode=component},ct));await Committed(editor.SetId,input.RequestId,ct);break;
   case "retire-parameter":var published=editor.Selected!;if(published.Status!=ParameterVersionStatus.Published)throw new InvalidOperationException("Select a published version first.");Read(await api.RetireAsync(new(){CommandId=input.RequestId,EntityId=new(editor.SetId),Version=published.Reference.Version,ExpectedRevision=editor.ExpectedRevision,ComponentCode=component},ct));await Committed(editor.SetId,input.RequestId,ct);break;
   case "rename-parameter":Read(await api.RenameAsync(new(){CommandId=input.RequestId,EntityId=new(editor.SetId),Version=editor.Selected!.Reference.Version,ExpectedRevision=editor.ExpectedRevision,ComponentCode=component,Name=input.Fields["name"],Description=input.Fields.GetValueOrDefault("description")??""},ct));await Committed(editor.SetId,input.RequestId,ct);break;
   case "schema-parameter":extras["schema"]=JsonSerializer.Serialize(Read(await api.SchemaAsync(editor.SchemaVersion,ct,component)));break;
   case "payload-parameter":extras["payload"]=editor.Payload();break;
   case "compare-parameter":var state=Read(await api.StateAsync(editor.SetId,ct));extras["comparisonVersions"]=JsonSerializer.Serialize(state.Versions.Select(x=>new{Id=Id(x),x.Name,x.Reference.Version}));var before=state.Versions.FirstOrDefault(x=>Id(x)==input.Fields.GetValueOrDefault("compareId"))??state.Versions.First();extras["differences"]=JsonSerializer.Serialize(ParameterComparisonModel.Compare(before.PayloadJson,editor.Payload()));break;
   case "audit-parameter":extras["audit"]=JsonSerializer.Serialize(Read(await api.StateAsync(editor.SetId,ct)));break;
   case "assignment":if(editor.Selected!.Status!=ParameterVersionStatus.Published)throw new InvalidOperationException("Select a published version first.");assignment=Read(await api.AssignmentAsync(Workflow,TargetHorizon(),ct));extras["assignment"]=JsonSerializer.Serialize(assignment);break;
   case "assign-parameter":case "disable-assignment":if(assignment is null||editor.Selected!.Status!=ParameterVersionStatus.Published||editor.Parameters is null)throw new InvalidOperationException("Load the published version assignment first.");if(input.Intent=="assign-parameter")Read(await api.AssignAsync(new(){CommandId=input.RequestId,EntityId=assignment.EntityId,Scope=assignment.Scope,Reference=editor.Selected.Reference,ExpectedRevision=assignment.Revision},ct));else {if(assignment.Assignment?.Enabled!=true)throw new InvalidOperationException("Assignment is already disabled.");Read(await api.DisableAssignmentAsync(new(){CommandId=input.RequestId,EntityId=assignment.EntityId,Scope=assignment.Scope,Reference=assignment.Assignment.Reference,ExpectedRevision=assignment.Revision},ct));}assignment=Read(await api.AssignmentAsync(Workflow,TargetHorizon(),ct));extras["assignment"]=JsonSerializer.Serialize(assignment);break;
   case "startup-preview":extras["startupPreview"]=JsonSerializer.Serialize(Read(await api.PreviewStartupAsync(Guid.NewGuid(),ct)));break;
   case "startup-runs":extras["startupRuns"]=JsonSerializer.Serialize(Read(await api.StartupRunsAsync(ct)));break;
   case "startup-report":extras["startupReport"]=JsonSerializer.Serialize(Read(await api.StartupReportAsync(Guid.Parse(input.Fields["runId"]),ct)));break;
   case "signal-monitoring":extras["signalMonitoring"]=JsonSerializer.Serialize(Read(await api.SignalMonitoringAsync(Guid.Parse(input.Fields["runId"]),ct)));break;
   case "legacy-parameters":legacyOffset=0;await Legacy(ct);break;
   case "legacy-next":if(legacy.Length<100)throw new InvalidOperationException("No more historical versions.");legacyOffset+=100;await Legacy(ct);break;
   case "legacy-prev":legacyOffset=Math.Max(0,legacyOffset-100);await Legacy(ct);break;
   case "legacy-preview":var historical=legacy.Single(x=>LegacyId(x)==input.Fields.GetValueOrDefault("legacyId"));legacyPreview=Read(await api.PreviewLegacyMigrationAsync(historical.Reference.SetId,historical.Reference.Version,ct));legacyPreviewId=LegacyId(historical);extras["legacyPreviewId"]=legacyPreviewId;extras["legacyPreview"]=JsonSerializer.Serialize(legacyPreview);break;
   case "legacy-create":if(editor.IsEditing)throw new InvalidOperationException("Save or discard the working copy before importing a historical version.");if(legacyPreview is null||input.Fields.GetValueOrDefault("legacyId")!=legacyPreviewId||!extras.ContainsKey("legacyPreview"))throw new InvalidOperationException("Preview an exact historical draft first.");Read(await api.CreateAsync(legacyPreview,ct));var imported=legacyPreview;legacyPreview=null;component=imported.ComponentCode;await Committed(imported.EntityId.SetId,imported.CommandId,ct);break;
   default:throw new ArgumentException("Unsupported parameter action.");
  }
  return Publication();
 }
 static readonly TimeFrameType[] TimeFrames=[TimeFrameType.FifteenSeconds,TimeFrameType.OneMinute,TimeFrameType.FiveMinutes,TimeFrameType.FifteenMinutes,TimeFrameType.OneHour,TimeFrameType.FourHours,TimeFrameType.Daily];
 void Capture(Dictionary<string,string> fields){if(!editor.IsEditing){if(fields.ContainsKey("changes")||fields.ContainsKey("signals")||fields.ContainsKey("observations"))throw new InvalidOperationException("Saved versions are read-only.");return;}if(fields.TryGetValue("name",out var name))editor.Name=name;if(fields.TryGetValue("description",out var description))editor.Description=description;if(fields.TryGetValue("changes",out var changes))editor.SetFields(JsonSerializer.Deserialize<ParameterField[]>(changes)??[]);
  if(editor.Parameters is {} parameters&&(fields.ContainsKey("signals")||fields.ContainsKey("observations"))){var signals=fields.TryGetValue("signals",out var signalsJson)?JsonSerializer.Deserialize<RegimeDiscoverySignalMetricConfiguration[]>(signalsJson)??[]:parameters.SignalMetrics??RegimeDiscoveryMetricConfigurationProjection.FromLegacySignals(parameters.ParameterSetId,parameters.SignalRequirements??[]);var observations=fields.TryGetValue("observations",out var observationsJson)?JsonSerializer.Deserialize<RegimeDiscoveryObservationMetricConfiguration[]>(observationsJson)??[]:parameters.ObservationMetrics??RegimeDiscoveryMetricConfigurationProjection.FromLegacyObservations(parameters.ParameterSetId,parameters.SignalRequirements??[]);if(signals.Any(x=>!Enum.IsDefined(x.Metric)||x.Metric==SignalMetricsType.Unknown||!TimeFrames.Contains(x.TimeFrame)||x.PeriodLength<=0||x.MaximumAgeSeconds<=0)||observations.Any(x=>!Enum.IsDefined(x.Metric)||x.Metric==ObservationMetricsType.Unknown||x.MaximumAgeSeconds<=0))throw new ArgumentException("Metric, timeframe, period and maximum age must be valid.");editor.SetMetrics(signals,observations);}}
 async Task LoadVersions(CancellationToken ct){editor.Clear();extras.Clear();assignment=null;if(component.Length==0){versions=[];return;}versions=Read(await api.VersionsAsync(token:ct,componentCode:component));if(versions.Length>0){var row=versions[0];editor.Load(row,versions.Where(x=>x.Reference.SetId==row.Reference.SetId).Max(x=>x.CatalogRevision));}}
 async Task Legacy(CancellationToken ct){legacy=Read(await api.LegacyVersionsAsync(legacyOffset,ct));legacyPreview=null;legacyPreviewId="";extras.Remove("legacyPreview");extras.Remove("legacyPreviewId");extras["legacyVersions"]=JsonSerializer.Serialize(legacy.Select(x=>new{Id=LegacyId(x),x.Reference,x.SchemaVersion,x.PayloadJson,x.Status}));extras["legacyOffset"]=legacyOffset.ToString();extras["legacyHasMore"]=(legacy.Length==100).ToString();}
 async Task Committed(Guid id,Guid operationId,CancellationToken ct){ParameterSetSnapshot state;try{state=Read(await api.StateAsync(id,ct));}catch(Exception error){throw new EditorOutcomeUnknownException("Commit acknowledged but authoritative refresh failed: "+error.Message);}var receipt=state.Operations.SingleOrDefault(x=>x.OperationId==operationId)??throw new EditorOutcomeUnknownException("Committed operation is not visible; refresh its outcome before further edits.");versions=versions.Where(x=>x.Reference.SetId!=id).Concat(state.Versions).ToArray();editor.Load(state.Versions.Single(x=>x.Reference==receipt.Reference),state.Revision);extras.Clear();assignment=null;}
 int TargetHorizon()=>editor.Parameters is {} parameters?(int)parameters.TargetHorizon:throw new InvalidOperationException("Only published Regime Discovery versions support this workflow assignment.");
 ContractEditorResult Publication(){var context=new Dictionary<string,string>(extras){["components"]=JsonSerializer.Serialize(components),["component"]=component,["editing"]=editor.IsEditing.ToString(),["canEdit"]=editor.CanEdit.ToString(),["name"]=editor.Name,["description"]=editor.Description,["selectedId"]=editor.Selected is {} selected?Id(selected):"",["revision"]=editor.ExpectedRevision.ToString(),["hasPayload"]=editor.HasPayload.ToString()};if(editor.HasPayload){context["fields"]=JsonSerializer.Serialize(ParameterFieldEditorModel.Read(editor.Payload()));context["payload"]=editor.Payload();context["signals"]=JsonSerializer.Serialize(editor.Parameters?.SignalMetrics??(editor.Parameters is {} p?RegimeDiscoveryMetricConfigurationProjection.FromLegacySignals(p.ParameterSetId,p.SignalRequirements??[]):[]));context["observations"]=JsonSerializer.Serialize(editor.Parameters?.ObservationMetrics??(editor.Parameters is {} op?RegimeDiscoveryMetricConfigurationProjection.FromLegacyObservations(op.ParameterSetId,op.SignalRequirements??[]):[]));context["intervals"]=JsonSerializer.Serialize(editor.Parameters?.Horizon.TimeFrames??[]);context["regime"]= (editor.Parameters is not null).ToString();}
  return new("parameter-sets",versions.Select(x=>new ContractEditorRow(Id(x),new(){["name"]=x.Name,["status"]=x.Status.ToString(),["version"]=x.Reference.Version.ToString(),["setId"]=x.Reference.SetId.ToString()})).ToArray(),new(){["horizons"]=["Daily","Weekly","Monthly"],["timeframes"]=TimeFrames.Select(x=>((int)x).ToString()).ToArray(),["timeframeNames"]=TimeFrames.Select(x=>x.ToString()).ToArray(),["signalMetricIds"]=Enum.GetValues<SignalMetricsType>().Where(x=>x!=SignalMetricsType.Unknown).Select(x=>((int)x).ToString()).ToArray(),["signalMetricNames"]=Enum.GetNames<SignalMetricsType>().Where(x=>x!="Unknown").ToArray(),["observationMetricIds"]=Enum.GetValues<ObservationMetricsType>().Where(x=>x!=ObservationMetricsType.Unknown).Select(x=>((int)x).ToString()).ToArray(),["observationMetricNames"]=Enum.GetNames<ObservationMetricsType>().Where(x=>x!="Unknown").ToArray()},Context:context);}
 static T Read<T>(ServiceResult<T> result){if(!result.Success||result.Value is null)throw new InvalidOperationException(result.ErrorMessage??"Parameter operation failed.");return result.Value;}
 static string Id(ParameterSetVersion row)=>row.Reference.SetId+":"+row.Reference.Version;
 static string LegacyId(ParameterLegacyVersion row)=>row.Reference.SetId+":"+row.Reference.Version;
 public async ValueTask DisposeAsync(){if(scope is not null)await scope.DisposeAsync();}
}
